import { test, expect } from '@receipts/core/fixture';
// scenario-hash video-resume: 6a482aa66c0631361369b0d7310a0473b09b6c26c5eba64b5b54333b5fc69e78
test.describe("video-resume", () => {
  test.use({ receiptsPersona: "learner", receiptsFlags: {"resume-playback":true}, receiptsRedact: [".avatar"], viewport: {"width":1280,"height":720} });

  test("Lesson video resumes from saved progress", { tag: ["@smoke","@video","@progress"] }, async ({ page, receipts }) => {
    // setup
    await receipts.api({"method":"DELETE","url":"/api/me/progress/lessons/intro-to-typography"});
    await test.step("1. Open lesson as signed-in learner", async () => {
      await receipts.chapter("Open lesson as signed-in learner", 1, 5);
      await page.goto(receipts.url("/lessons/intro-to-typography"));
      await expect(page.getByRole("region", { name: "Lesson video" }), "role=region[name=\"Lesson video\"] is visible").toBeVisible();
      await expect.poll(() => receipts.mediaTime("video"), "video currentTime ≤ 1").toBeLessThanOrEqual(1);
      await receipts.capture("opened");
    });
    await test.step("2. Watch ~40 seconds", async () => {
      await receipts.chapter("Watch ~40 seconds", 2, 5);
      await receipts.media({"play":true,"seek":40,"muted":true,"waitForTime":42});
      await expect.poll(() => receipts.requestCount({ method: "PUT", url: "/api/me/progress/**" }), "PUT /api/me/progress/** called >=1 time(s)").toBeGreaterThanOrEqual(1);
      await receipts.capture("playing-at-40s");
    });
    await test.step("3. Leave the lesson", async () => {
      await receipts.chapter("Leave the lesson", 3, 5);
      await page.goto(receipts.url("/courses"));
      await receipts.capture("left-lesson");
    });
    await test.step("4. Return to the lesson", async () => {
      await receipts.chapter("Return to the lesson", 4, 5);
      await page.goto(receipts.url("/lessons/intro-to-typography"));
      await page.waitForSelector("video", { state: "attached" });
      await expect.poll(async () => Math.abs((await receipts.mediaTime("video")) - 42), "video currentTime ≈ 42 ± 3s").toBeLessThanOrEqual(3);
      await expect(page.getByText(/Resuming from 0:4\d/), "text /Resuming from 0:4\\d/ is visible").toBeVisible();
      // 🤖 AI-judged (only evaluated by `receipts run` with ai.judge enabled): "The player shows a 'Resuming from' indicator near 0:42 and is not at 0:00"
      await receipts.judge("The player shows a 'Resuming from' indicator near 0:42 and is not at 0:00");
      await receipts.capture("resumed");
    });
    await test.step("5. Health", async () => {
      await receipts.chapter("Health", 5, 5);
      expect(receipts.consoleErrors(), "0 console errors").toBeLessThanOrEqual(0);
    });
  });
});

